(* ================================================================= *)
(*  BaselZeta16Poly.v  —  the Newton p₈ polynomial identity.          *)
(*  Standalone algebraic identity in one real variable x, minimal     *)
(*  imports so the degree-16 [field] stays fast.                      *)
(* ================================================================= *)

From Stdlib Require Import Reals Lra.
Open Scope R_scope.

Lemma cot16_poly_id : forall x : R,
  (x*(2*x-1)/3)^8
    - 8*(x*(2*x-1)/3)^6*((16*x^4 - 48*x^3 + 44*x^2 - 12*x) / 120)
    + 20*(x*(2*x-1)/3)^4*((16*x^4 - 48*x^3 + 44*x^2 - 12*x) / 120)^2
    + 8*(x*(2*x-1)/3)^5*((64*x^6 - 480*x^5 + 1360*x^4 - 1800*x^3 + 1096*x^2 - 240*x) / 5040)
    - 16*(x*(2*x-1)/3)^2*((16*x^4 - 48*x^3 + 44*x^2 - 12*x) / 120)^3
    - 32*(x*(2*x-1)/3)^3*((16*x^4 - 48*x^3 + 44*x^2 - 12*x) / 120)*((64*x^6 - 480*x^5 + 1360*x^4 - 1800*x^3 + 1096*x^2 - 240*x) / 5040)
    - 8*(x*(2*x-1)/3)^4*((256*x^8 - 3584*x^7 + 20608*x^6 - 62720*x^5 + 108304*x^4 - 105056*x^3 + 52272*x^2 - 10080*x) / 362880)
    + 2*((16*x^4 - 48*x^3 + 44*x^2 - 12*x) / 120)^4
    + 24*(x*(2*x-1)/3)*((16*x^4 - 48*x^3 + 44*x^2 - 12*x) / 120)^2*((64*x^6 - 480*x^5 + 1360*x^4 - 1800*x^3 + 1096*x^2 - 240*x) / 5040)
    + 12*(x*(2*x-1)/3)^2*((64*x^6 - 480*x^5 + 1360*x^4 - 1800*x^3 + 1096*x^2 - 240*x) / 5040)^2
    + 24*(x*(2*x-1)/3)^2*((16*x^4 - 48*x^3 + 44*x^2 - 12*x) / 120)*((256*x^8 - 3584*x^7 + 20608*x^6 - 62720*x^5 + 108304*x^4 - 105056*x^3 + 52272*x^2 - 10080*x) / 362880)
    + 8*(x*(2*x-1)/3)^3*((1024*x^10 - 23040*x^9 + 222720*x^8 - 1209600*x^7 + 4049472*x^6 - 8618400*x^5 + 11578880*x^4 - 9381600*x^3 + 4106304*x^2 - 725760*x) / 39916800)
    - 8*((16*x^4 - 48*x^3 + 44*x^2 - 12*x) / 120)*((64*x^6 - 480*x^5 + 1360*x^4 - 1800*x^3 + 1096*x^2 - 240*x) / 5040)^2
    - 8*((16*x^4 - 48*x^3 + 44*x^2 - 12*x) / 120)^2*((256*x^8 - 3584*x^7 + 20608*x^6 - 62720*x^5 + 108304*x^4 - 105056*x^3 + 52272*x^2 - 10080*x) / 362880)
    - 16*(x*(2*x-1)/3)*((64*x^6 - 480*x^5 + 1360*x^4 - 1800*x^3 + 1096*x^2 - 240*x) / 5040)*((256*x^8 - 3584*x^7 + 20608*x^6 - 62720*x^5 + 108304*x^4 - 105056*x^3 + 52272*x^2 - 10080*x) / 362880)
    - 16*(x*(2*x-1)/3)*((16*x^4 - 48*x^3 + 44*x^2 - 12*x) / 120)*((1024*x^10 - 23040*x^9 + 222720*x^8 - 1209600*x^7 + 4049472*x^6 - 8618400*x^5 + 11578880*x^4 - 9381600*x^3 + 4106304*x^2 - 725760*x) / 39916800)
    - 8*(x*(2*x-1)/3)^2*((4096*x^12 - 135168*x^11 + 1971200*x^10 - 16727040*x^9 + 91500288*x^8 - 337607424*x^7 + 853730240*x^6 - 1471863360*x^5 + 1684129216*x^4 - 1207343808*x^3 + 482175360*x^2 - 79833600*x) / 6227020800)
    + 4*((256*x^8 - 3584*x^7 + 20608*x^6 - 62720*x^5 + 108304*x^4 - 105056*x^3 + 52272*x^2 - 10080*x) / 362880)^2
    + 8*((64*x^6 - 480*x^5 + 1360*x^4 - 1800*x^3 + 1096*x^2 - 240*x) / 5040)*((1024*x^10 - 23040*x^9 + 222720*x^8 - 1209600*x^7 + 4049472*x^6 - 8618400*x^5 + 11578880*x^4 - 9381600*x^3 + 4106304*x^2 - 725760*x) / 39916800)
    + 8*((16*x^4 - 48*x^3 + 44*x^2 - 12*x) / 120)*((4096*x^12 - 135168*x^11 + 1971200*x^10 - 16727040*x^9 + 91500288*x^8 - 337607424*x^7 + 853730240*x^6 - 1471863360*x^5 + 1684129216*x^4 - 1207343808*x^3 + 482175360*x^2 - 79833600*x) / 6227020800)
    + 8*(x*(2*x-1)/3)*((16384*x^14 - 745472*x^13 + 15282176*x^12 - 186554368*x^11 + 1509860352*x^10 - 8534862336*x^9 + 34569337088*x^8 - 101240723584*x^7 + 213511602304*x^6 - 318646520192*x^5 + 325020049536*x^4 - 212773736448*x^3 + 79211036160*x^2 - 12454041600*x) / 1307674368000)
    - 8*((65536*x^16 - 3932160*x^15 + 107806720*x^14 - 1789132800*x^13 + 20068851712*x^12 - 160887767040*x^11 + 950370037760*x^10 - 4202305536000*x^9 + 13985569165568*x^8 - 34918810967040*x^7 + 64619014853120*x^6 - 86618027059200*x^5 + 80911931261184*x^4 - 49326540917760*x^3 + 17356652006400*x^2 - 2615348736000*x) / 355687428096000)
  = (355565568*x^16 + 2844524544*x^15 + 5987696640*x^14 - 7865303040*x^13 - 37908242432*x^12
     + 4225351680*x^11 + 113821052928*x^10 + 3943976960*x^9 - 229552173312*x^8 + 36110638080*x^7
     + 320686408960*x^6 - 178793005824*x^5 - 249204536352*x^4 + 355069137600*x^3 - 168379722000*x^2
     + 28733079375*x) / 488462349375.
Proof. intros x; field. Qed.

Print Assumptions cot16_poly_id.
